use serde_json::{json, Value as JsonValue};

use super::super::activation::require_authority;
use super::super::effects::recovery_is_fenced;
use super::super::{ModuleRuntime, PinnedCall};

impl ModuleRuntime<'_> {
    pub(super) fn rollback(
        &self,
        expected_record_cid: &str,
        expected_module_cid: &str,
        expected_epoch: u64,
        authorization: &str,
    ) -> Result<JsonValue> {
        if let Err(err) = require_authority(authorization) {
            return self.response(
                "rollback_rejected",
                "rejected",
                json!({"message": err.to_string()}),
            );
        }
        let pinned = PinnedCall {
            call_id: "explicit-rollback-frontier".to_owned(),
            record_cid: expected_record_cid.to_owned(),
            module_cid: expected_module_cid.to_owned(),
            epoch: expected_epoch,
            state_cid: None,
            state_extension_cid: None,
            state_revision_cid: None,
            state_revision: None,
        };
        {
            let state = self.lock_state()?;
            if recovery_is_fenced(&state) {
                drop(state);
                return self.recovery_fence_rejection();
            }
            let current = state
                .epochs
                .get(&state.current_epoch)
                .context("runtime current epoch is missing")?;
            if state.current_record_cid != pinned.record_cid
                || state.current_epoch != pinned.epoch
                || current.module_cid != pinned.module_cid
            {
                drop(state);
                return self.response(
                    "rollback_rejected",
                    "rejected",
                    json!({"message": "stale rollback frontier"}),
                );
            }
            if current.state_cid.is_some() {
                drop(state);
                return self.response(
                    "rollback_rejected",
                    "rejected",
                    json!({"message": "stateful frontier requires an explicit stateful rollback contract"}),
                );
            }
            if current.rollback_module_cid.is_none() {
                drop(state);
                return self.response(
                    "rollback_rejected",
                    "rejected",
                    json!({"message": "current frontier has no verified rollback target"}),
                );
            }
        }
        let preparation = self.prepare_rollback(&pinned)?;
        let mut state = self.lock_state()?;
        let outcome = self.rollback_if_current(&mut state, &pinned, preparation)?;
        let committed = outcome.status == "rolled_back";
        let rollback_epoch = committed.then_some(state.current_epoch);
        drop(state);
        self.response(
            if committed {
                "rollback_committed"
            } else {
                "rollback_rejected"
            },
            if committed { "ok" } else { "rejected" },
            json!({
                "rollback_status": outcome.status,
                "rollback_message": outcome.message,
                "rollback_record_cid": outcome.record_cid,
                "rollback_epoch": rollback_epoch,
                "expected_record_cid": expected_record_cid,
                "expected_module_cid": expected_module_cid,
                "expected_epoch": expected_epoch,
            }),
        )
    }
